const base = String($env.REVIEW_BASE_URL || 'http://localhost:5678').replace(/\/$/, '');
const cut = (s, n) => {
  const v = String(s ?? '');
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

return $input.all()
  .filter(i => i.json && i.json.id)
  .map(i => {
    const r = i.json;
    const reviewUrl = `${base}/webhook/backlink-review?id=${encodeURIComponent(r.id)}&token=${encodeURIComponent(r.review_token)}`;
    return {
      json: {
        discordPayload: {
          username: 'SyaCo Backlink Bot',
          embeds: [{
            title: cut(`[${r.platform}] ${r.post_title}`, 250),
            url: r.post_url,
            description: `**Review and approve:** ${reviewUrl}`,
            color: 5793266,
            fields: [
              { name: 'Solution', value: cut(r.solution_title || '-', 1000), inline: true },
              { name: 'Match score', value: String(r.match_score), inline: true },
              { name: 'Link included', value: r.link_included ? 'yes' : 'no', inline: true },
              { name: 'Matched problem', value: cut(r.matched_problem || '-', 1000) },
              { name: 'Draft answer', value: cut(r.answer || '-', 1000) }
            ]
          }]
        }
      }
    };
